import hashlib
import math

class BloomFilter:
    """
    A BloomFilter is a probabilistic data structure designed to 
    check membership of elements while allowing for a controlled 
    false positive rate. This implementation emphasizes memory efficiency
    by utilizing a bit array and deterministic hashing without relying 
    on external libraries.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_hash_functions()
        self.bit_array = [0] * self.size

    def _calculate_bit_array_size(self) -> int:
        """Calculates the size of the bit array using the expected items and false positive rate."""
        return int(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_hash_functions(self) -> int:
        """Calculates the optimal number of hash functions to use."""
        return max(1, min(self.size, int((self.size / self.expected_items) * math.log(2))))

    def _simple_hash(self, item: str, seed: int) -> int:
        """Generates a hash value based on the item and a seed for unique results."""
        hasher = hashlib.sha256()
        hasher.update(f"{seed}:{item}".encode('utf-8'))
        return int(hasher.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Adds an item to the Bloom filter by setting appropriate bits."""
        for i in range(self.hash_count):
            index = self._simple_hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Checks if the item may be in the Bloom filter."""
        for i in range(self.hash_count):
            index = self._simple_hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True

